"""Update the blind comparison with completed one-fault-at-a-time Lean trials."""

import html
import json
from pathlib import Path
import re
from statistics import median

from common import BASE, ROOT
from run_isolated_theory import RUN_ID

run = BASE / "runs" / RUN_ID
prior = BASE / "runs/20261112-blind-theory-01"
data = json.loads((run / "scoring.json").read_text())
summary = data["summary"]
validation = json.loads((run / "validation.json").read_text())
assert validation["status"] == "passed" and summary["cases"] == 100
agents = json.loads((prior / "scoring.json").read_text())["summary"]
requirements = json.loads((run / "requirements.json").read_text())
esc = lambda value: html.escape(str(value))


def link(path, label, line=1):
    return f'<a href="vscode://file{esc(str(path.resolve()))}:{line}">{esc(label)}</a>'


def badge(detected):
    return '<span class="badge found">Rejected</span>' if detected else '<span class="badge miss">Accepted</span>'


css = re.search(r"<style>(.*?)</style>", (run / "previous-report.html").read_text(), re.S)[1]
css += '.method-note{font-size:15px}.status-count{font-size:24px;font-weight:750}.case-detail .log{font-size:12px}details>summary{cursor:pointer;font-weight:650}th small{display:block;font-weight:400}input,select{max-width:100%}.sensitivity{border-left-color:var(--amber)}'
rows = []
for r in data["by_requirement"]:
    rows.append(f'<tr><th>{r["requirement"]}</th><td>{esc(r["description"])}</td><td>{r["rejected"]}/5</td><td>{r["accepted"]}/5</td></tr>')

case_rows = []
for i, row in enumerate(data["cases"]):
    folder = run / "cases" / row["case_id"]
    result = json.loads((folder / "lean/result.json").read_text())
    logs = []
    for proof in result["proofs"]:
        logs.append('<p>' + link(folder / "lean" / proof["source"], proof["source"]) + ': ' + ('passed' if proof['returncode'] == 0 else 'rejected') + '. ' + link(folder / "lean" / (Path(proof["source"]).stem + '.jsonl'), 'Complete Lean output') + '</p>')
        for error in proof["errors"]:
            logs.append('<p>' + link(folder / "lean" / proof["source"], 'Failing proof condition', error["pos"]["line"]) + '</p>')
            logs.append('<div class="log">' + esc(error["data"]) + '</div>')
    req = requirements[row["requirement"]]
    body = f'<p><b>{esc(row["description"])}</b></p><p class="quote">{esc(req["text"])}</p><p>Original PDF page {req["page"]}. Exactly one mutation was applied. The live check observed its intended behavior, and the snapshot passed the before/after stability checks.</p>'
    if row["ground_truth_status"] != "supported":
        body += '<p><b>Qualified case:</b> the packet is accepted, but the alternative paths prevent a conclusive claim that its source is forbidden on the receiving interface.</p>'
    body += '<div class="source-links">' + ''.join([
        link(folder / "before.json", "Clean state before injection"),
        link(folder / "single-profile.json", "Single injected case"),
        link(folder / "public/oracle/single-fault" / (row["network"] + '.json'), "Live behavior check"),
        link(folder / "snapshot/native/snapshot.json", "Fresh snapshot"),
        link(folder / "snapshot/native/manifest.json", "Snapshot integrity and stability"),
        link(folder / "lean/input.json", "Imported Lean data"),
        link(folder / "restored.json", "Verified clean restoration"),
    ]) + '</div>' + ''.join(logs)
    search = ' '.join([row["case_id"], row["device"], row["description"]]).lower()
    case_rows.append(f'<tr class="case" data-search="{esc(search)}" data-network="{row["network"]}" data-outcome="{row["status"]}"><th>{row["network"]}<small>{esc(row["device"])}</small></th><td>{row["requirement"]}'+(' <span class="badge related">Ambiguous</span>' if row["ground_truth_status"] != "supported" else '')+f'</td><td>{badge(row["tdn_detected"])}</td><td>{row["lean_seconds"]:.1f} s</td><td><button class="req-button" data-detail="case-{i}" aria-expanded="false">Evidence</button></td></tr><tr class="case-detail" id="case-{i}" hidden><td colspan="5">{body}</td></tr>')

network_rows = []
for path in sorted((run / 'profiles').glob('net-*.json')):
    p = json.loads(path.read_text())
    cases = [r for r in data['cases'] if r['network'] == p['network']]
    network_rows.append(f'<tr><th>{p["network"]}</th><td>{p["source_profile"]}</td><td>{len(p["topology"]["devices"])}</td><td>20</td><td>{sum(r["tdn_detected"] for r in cases)}</td><td>{sum(not r["tdn_detected"] for r in cases)}</td></tr>')

misses = [r for r in data['by_requirement'] if r['accepted']]
miss_rows = ''.join(f'<tr><th>{r["requirement"]}</th><td>{esc(r["description"])}</td><td>{r["accepted"]}</td></tr>' for r in misses)
changes = summary['differences_from_previous_attribution']
comparison = ('The isolated runs confirm the same set of configurations associated with errors in the earlier multi-fault experiment.' if not changes else f'The isolated runs change the earlier attribution for {len(changes)} cases: ' + ', '.join(changes) + '.')
agent_rows = ''.join(f'<tr><th>{label}</th><td>{agents[model]["faults_identified"]}/100</td><td>{agents[model]["sensitivity_faults_identified"]}/99</td><td>{agents[model]["runtime_seconds"]/60:.2f} minutes</td></tr>' for model, label in [('astra','GPT-6 Astra High'),('sol','GPT-6 Sol High')])
proof_median = median(r['lean_seconds'] for r in data['cases'])

page = f'''<!doctype html><html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>TDN v3.3 | Blind audits and isolated fault tests</title><style>{css}</style></head><body><div class="layout"><nav class="nav"><div class="brand">TDN v3.3</div><p>Updated experiment<br>12 November 2026</p><a href="#results">Updated results</a><a href="#method">One fault at a time</a><a href="#checks">What Lean checks</a><a href="#misses">What TDN missed</a><a href="#coverage">Requirement coverage</a><a href="#cases">Individual cases</a><a href="#agents">Blind Detector results</a><a href="#timing">Runtime</a><a href="#limits">Limits and records</a><button id="theme">Dark theme</button></nav><main>
<header><div class="eyebrow">Fresh live snapshots and actual Lean proof attempts</div><h1>TDN tested with one injected fault at a time</h1><p class="intro">Each network returned to its checked clean configuration before the next case. The runner applied one change, verified it on the devices, collected a fresh snapshot, and ran Lean before restoring the network.</p><p>The Astra and Sol findings remain the earlier blind audits. Neither agent received questions, selected requirements, fault counts, or previous results.</p></header>
<section id="results"><h2>Lean rejected {summary['detected']} of the 100 individually faulty snapshots</h2><div class="stats"><div class="stat"><small>Detected by the selected proofs</small><strong>{summary['detected']} / 100</strong><span>Actual Lean rejection after one live mutation</span></div><div class="stat"><small>Not detected by the selected proofs</small><strong>{summary['not_detected']} / 100</strong><span>The two proof applications passed despite the planted fault</span></div><div class="stat"><small>Clean controls</small><strong>5 / 5</strong><span>Both proof applications passed in the clean state</span></div></div><p>{comparison}</p><p>The previous report used several simultaneous mutations and separate rule checks to attribute errors. The new result comes from <b>100 complete, separately collected faulty network snapshots</b>. Each case now has its own import, Lean output, live observation, and clean-restoration record.</p>
<div class="note sensitivity"><p><b>One intended fault remains ambiguous.</b> The net-04 PF-18 packet is accepted, but the redundant paths leave uncertainty about whether its claimed source is forbidden on that interface. Excluding that case gives <b>{summary['supported_detected']}/{summary['supported_cases']}</b> detected supported faults. The report retains the qualified case for reproducibility.</p></div>
<div class="table-wrap"><table><thead><tr><th>Network</th><th>Profile</th><th>Devices</th><th>Isolated cases</th><th>Rejected</th><th>Accepted</th></tr></thead><tbody>{''.join(network_rows)}</tbody></table></div></section>
<section id="method"><h2>Every case follows the same sequence</h2><ol><li><b>Verify the clean starting state.</b> Public configuration files, ordered filters, routes, routing tables, interface states, and source-address settings must match the clean control.</li><li><b>Apply one recorded mutation.</b> The journal contains exactly one selected case. Changes at both tunnel endpoints are included when the intended fault requires the peers to agree.</li><li><b>Check the actual behavior.</b> A packet probe or loaded-configuration inspection must observe the intended change. Every tunnel endpoint must have an installed data tunnel.</li><li><b>Collect a fresh snapshot.</b> The collectors read all devices and retain their raw outputs. Before/after comparisons check that selected configuration and topology fields stayed stable during collection.</li><li><b>Import and typecheck.</b> The existing parser produces typed JSON records. The same two Lean applications attempt their proofs for every case.</li><li><b>Restore and verify.</b> The runner restores the clean files and runtime settings, establishes the tunnels, and checks the clean-state fingerprints before continuing.</li></ol>
<p>The five independent networks run in parallel. Within each network, collection, Lean checking, and restoration finish before the next mutation begins. All five networks are left in their clean configurations.</p><p>The snapshot collector skips unrelated all-host ping tests and management TLS probes. Their omission is recorded explicitly. The designated fault still receives a live check, and all configuration/state collection and stability checks remain enabled.</p><p>The run corrected a Python archive-reader compatibility error and tightened the IPsec settling checks. Earlier captures containing sessions still closing were retained and repeated. Parallel fully established tunnels are allowed; an intermediate single-session restriction was too strict and was corrected. A later connection interruption stopped the runners; the affected cases were restored and repeated. All preparation failures, interrupted attempts, and repeated captures remain recorded and are excluded from the final hundred-case score.</p><div class="source-links">{link(BASE/'run_isolated_theory.py','Sequential experiment driver')}{link(BASE/'isolated_worker.py','Live mutation, collection, and restoration')}{link(run/'events.jsonl','Complete chronological record')}{link(run/'implementation-revisions.json','Runner repair record')}{link(run/'connection-interruption.json','Connection interruption and recovery')}{link(run/'freeze.json','Frozen theory, parsers, and proof templates')}</div></section>
<section id="checks"><h2>The same existing proofs are applied to every snapshot</h2><div class="cards"><article class="card"><h3>Double encryption at Black interfaces</h3><p><code>SnapshotCompliance.lean</code> applies <code>protected_red_stack_from_local_checks</code>. Its supporting conditions check routes, links, switching, firewall rules, and the required encapsulation layers.</p></article><article class="card"><h3>Allowed protocols and multicast restrictions</h3><p><code>HeaderCompliance.lean</code> applies the existing accepted-protocol and external-unicast theorems. Its conditions inspect the captured INPUT, FORWARD, and OUTPUT rules as required by each property.</p></article></div>
<p>The experiment changes the supplied network records, while the general proofs and proof templates remain fixed. Lean reports a rejection when <code>native_decide</code> finds that a required finite condition is false. Import errors and compiler failures have separate outcomes; neither counts as a detected violation. Each injected case counts once, even if several proof conditions fail.</p><p>A failed sufficient condition blocks the global proof. That failure does not automatically prove the global property's negation. The isolated experiment establishes which single change causes the failure, and the independent live check confirms the planted behavior.</p><p>Successful checking means the selected modeled properties passed. It does not certify every CSfC requirement. These applications cover the data-plane stack and protocol/multicast properties; they do not run every selected RG theorem. The accepted trust assumptions include Lean's compiler and native toolchain used by <code>native_decide</code>.</p><div class="source-links">{link(run/'sources/SnapshotCompliance.lean','Fixed data-plane proof application')}{link(run/'sources/HeaderCompliance.lean','Fixed protocol and multicast applications')}{link(ROOT/'TDN/Requirements/DoubleEncryptionOnBlackLinks.lean','General double-encryption theorem')}{link(run/'validation.json','Validation of all completed trials')}</div></section>
<section id="misses"><h2>The accepted faulty snapshots show the checks' coverage gaps</h2><p>The following injected cases passed both Lean applications. Each case has a confirmed live change and a fresh snapshot, so the accepted result is recorded as a missed fault by the selected suite.</p><div class="table-wrap"><table><thead><tr><th>Requirement</th><th>Injected change that passed Lean</th><th>Cases</th></tr></thead><tbody>{miss_rows}</tbody></table></div><p>The project's selected proof suite does not test algorithm choices, certificate uniqueness, authentication settings, lifetime limits, spare-interface shutdown, or the Outer Firewall's HTTP application restriction. Passing the packet-processing proofs therefore leaves those requirements unchecked. Eight of these requirement types, covering forty cases, are assigned to direct configuration checks in TDN's current design. The five HTTP-service cases account for the remaining gap. No Python configuration-audit findings supplement the Lean detection score.</p><p>Some detected changes violate a different condition from the targeted document clause. For example, the spoofed-source and unlisted-peer allowances also bypass required encryption processing. Their stack-check failures detect the configuration change but do not establish PF-18 or PF-17 specifically. The requirement table reports whether the injected fault causes any selected Lean proof to fail.</p></section>
<section id="coverage"><h2>Each requirement type was tested separately on all five networks</h2><div class="table-wrap"><table><thead><tr><th>Target requirement</th><th>Injected change</th><th>Lean rejected</th><th>Lean accepted</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div></section>
<section id="cases"><h2>Inspect the snapshot and Lean result for any case</h2><div class="controls"><label>Search cases<input id="search" placeholder="Requirement, device, or change"></label><label>Network<select id="network"><option value="">All networks</option>{''.join(f'<option>net-{i:02}</option>' for i in range(1,6))}</select></label><label>Lean result<select id="outcome"><option value="">All results</option><option value="rejected_by_Lean">Rejected: detected change</option><option value="accepted_by_Lean">Accepted: missed change</option></select></label></div><p id="count">100 cases</p><div class="table-wrap"><table id="case-table"><thead><tr><th>Network and device</th><th>Target</th><th>Lean result</th><th>Checking time</th><th>Details</th></tr></thead><tbody>{''.join(case_rows)}</tbody></table></div></section>
<section id="agents"><h2>The blind Detector results remain unchanged</h2><div class="table-wrap"><table><thead><tr><th>Method</th><th>Faults identified, nominal cases</th><th>Supported cases only</th><th>Agent runtime</th></tr></thead><tbody>{agent_rows}<tr><th>TDN isolated proof applications</th><td>{summary['detected']}/100</td><td>{summary['supported_detected']}/99</td><td>See the separate collection and checking measurements</td></tr></tbody></table></div><p>Astra and Sol each audited five networks containing twenty simultaneous mutations. They discovered requirements from the original PDF and inspected read-only device observations. TDN now tests those mutations individually. The table compares coverage of the intended cases; it does not claim that the three methods ran under identical mutation schedules.</p><p>Astra identified all 99 supported faulty configurations and cited the intended requirement for 94. Sol identified 95 supported faulty configurations and cited the intended requirement for 80. The remaining label differences were correct reports under another applicable requirement. Sol's four confirmed misses concern source-address checks. Astra explicitly withheld the ambiguous net-04 case.</p><p>The original audit reviewed 104 unique Astra requirement claims and 85 unique Sol requirement claims. All were supported within their stated scope. The agents had no clean-negative trial, so ordinary accuracy and specificity are unavailable. Filesystem blindness was instructed and checked through recorded commands; the network gateway enforced a read-only allowlist. No unauthorized access was observed.</p><div class="source-links">{link(prior/'astra/prompt.txt','Astra prompt')}{link(prior/'sol/prompt.txt','Sol prompt')}{link(prior/'astra/output/findings.json','Astra findings')}{link(prior/'sol/output/findings.json','Sol findings')}{link(prior/'scoring.json','Original Detector scoring')}{link(prior/'validation.json','Detector evidence validation')}</div></section>
<section id="timing"><h2>Runtime separates live experiments from Lean checking</h2><div class="table-wrap"><table><thead><tr><th>Measurement</th><th>Observed value</th><th>Included work</th></tr></thead><tbody><tr><th>Complete isolated experiment</th><td>{summary['wall_seconds']/60:.2f} minutes</td><td>Clean controls, one hundred mutations, live checks, snapshots, imports, Lean, and restoration. Includes the recorded runner repairs, connection interruption, and recovery.</td></tr><tr><th>Median Lean time per faulty snapshot</th><td>{proof_median:.2f} seconds</td><td>Both fixed proof applications; durations include waiting for a local compilation slot.</td></tr><tr><th>Sum of faulty-snapshot Lean job durations</th><td>{summary['lean_job_seconds']/60:.2f} minutes</td><td>Overlapping jobs; this sum is not wall-clock elapsed time.</td></tr><tr><th>Final Lean file checks</th><td>210</td><td>Two Lean files for each of 100 faulty snapshots and five clean controls.</td></tr><tr><th>Earlier retained attempts</th><td>{summary['retained_earlier_attempts']}</td><td>Preparation failures, interrupted attempts, and captures repeated after improving the session-settling check.</td></tr><tr><th>All Lean file checks, including retained repeats</th><td>{summary['all_lean_file_checks_including_repeats']}</td><td>The final score uses one settled snapshot per intended case.</td></tr></tbody></table></div><p>The agents' audit runtimes and the isolated TDN experiment measure different workloads. The TDN experiment repeatedly changes and restores the deployments to establish fault attribution. No direct speed advantage is claimed from those totals.</p></section>
<section id="limits"><h2>The records support isolated attribution within the selected proof scope</h2><ul><li>One injected change can affect several requirements. The experiment isolates the configuration change, not every semantic consequence.</li><li>The same twenty mutation patterns recur across five architectures. They are not one hundred independently sampled defect types.</li><li>Before/after observations show stability in selected fields. The collectors do not produce an atomic snapshot of every running process.</li><li>Lean checks the imported model. The test does not verify the parser or Linux implementation end to end.</li><li>The ambiguous source-address case remains qualified and is excluded from the supported-case score.</li></ul><p>All prior records are preserved. The new run stores the clean controls, every isolated snapshot, source and input hashes, actual Lean errors, live observations, and restoration checks. No changes were committed or pushed.</p><div class="source-links">{link(run/'scoring.json','All scores and case outcomes')}{link(run/'validation.json','Completed-run validation')}{link(BASE/'README-isolated-theory.md','Reproduction and scope')}{link(BASE/'score_isolated_theory.py','Validation and scoring code')}{link(run/'previous-report.html','Previous multi-fault report')}</div><p>The report retains the project's existing light Lavish design.</p></section><footer>TDN v3.3 | Isolated experiment {RUN_ID}</footer></main></div>
<script>document.getElementById('theme').onclick=()=>{{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';document.getElementById('theme').textContent=dark?'Light theme':'Dark theme'}};for(const button of document.querySelectorAll('[data-detail]'))button.onclick=()=>{{const row=document.getElementById(button.dataset.detail);row.hidden=!row.hidden;button.setAttribute('aria-expanded',String(!row.hidden))}};function filter(){{const search=document.getElementById('search').value.toLowerCase(),network=document.getElementById('network').value,outcome=document.getElementById('outcome').value;let n=0;for(const row of document.querySelectorAll('tr.case')){{const visible=row.dataset.search.includes(search)&&(!network||row.dataset.network===network)&&(!outcome||row.dataset.outcome===outcome);row.hidden=!visible;if(!visible){{row.nextElementSibling.hidden=true;row.querySelector('button').setAttribute('aria-expanded','false')}}n+=visible?1:0}}document.getElementById('count').textContent=n+' cases shown'}}for(const id of ['search','network','outcome'])document.getElementById(id).addEventListener('input',filter);</script></body></html>'''
followup = BASE / 'runs/20261112-perimeter-theory-02'
if (followup / 'validation.json').exists():
    from perimeter.build_report import augment
    page = augment(page, followup)
destination = ROOT / '.lavish/blind-theory-comparison.html'
destination.write_text(page)
print(json.dumps({'report': str(destination), 'cases': 100, 'bytes': destination.stat().st_size}))
